using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using System.Linq;
using System.IO;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            string text = "Scene=" + EditorSceneManager.GetActiveScene().path + " dirty=" + EditorSceneManager.GetActiveScene().isDirty + "\n";
            foreach (var f in new[]{"WORKSHOP", "MECHANISM", "EVIDENCE", "Khai"})
            {
                var g = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Art/InvestigationV36/R102/" + f + ".fbx");
                text += f + ": " + string.Join("|", g.GetComponentsInChildren<Transform>(true).Select(t => t.name + " " + t.localPosition + " " + t.localScale)) + "\n";
            }

            File.WriteAllText("Test/KetQua/investigation_r102/import-hierarchy.txt", text);
            r.Log(text);
        }
    }
}

